    \item We are given the vector $\mathbf{v} = \begin{pmatrix} 3 \\ 1 \end{pmatrix}$.  The unit vector along the $y$-axis is $\mathbf{j} = \begin{pmatrix} 0 \\ 1 \end{pmatrix}$.

    \item  Compute the dot product of $\mathbf{v}$ and $\mathbf{j}$:
    \[ \mathbf{v} \cdot \mathbf{j} = \begin{pmatrix} 3 \\ 1 \end{pmatrix} \cdot \begin{pmatrix} 0 \\ 1 \end{pmatrix} = (3)(0) + (1)(1) = 1. \]

    \item  Compute the squared norm of the unit vector $\mathbf{j}$:
    \[ \|\mathbf{j}\|^2 = 0^2 + 1^2 = 1. \]

    \item  Compute the scalar factor:
    \[ \frac{\mathbf{v} \cdot \mathbf{j}}{\|\mathbf{j}\|^2} = \frac{1}{1} = 1. \]

    \item  Compute the projection:
    \[ \text{proj}_{\mathbf{j}} \mathbf{v} = 1 \cdot \mathbf{j} = \begin{pmatrix} 0 \\ 1 \end{pmatrix}. \]

    \item  Therefore, the matrix that corresponds to projecting onto the $y$-axis is $\begin{pmatrix} 0 & 0 \\ 0 & 1 \end{pmatrix}$.
\end{enumerate}
